import Dexie, { type EntityTable } from "dexie";

/** Metadata for a file attached to a message (the blob lives in `files`). */
export type FileMeta = {
    /** same uuid as the owning message */
    id: string;
    name: string;
    type: string;
    size: number;
};

/** A single chat message, persisted locally in IndexedDB via Dexie. */
export type Message = {
    /** uuid generated by the sender — used for de-duplication across peers */
    id: string;
    /** the other participant of this conversation */
    peerId: number;
    from: number;
    to: number;
    body: string;
    ts: number;
    dir: "in" | "out";
    /**
     * out: pending → sent → delivered. `in` messages are always "delivered".
     * "failed" is terminal for a file the peer rejected / we could not resend.
     */
    status: "pending" | "sent" | "delivered" | "failed";
    /** present when this message carries a file instead of text */
    file?: FileMeta;
    /** why an outgoing file could not be delivered */
    error?: string;
};

/** File bytes received over the data channel, keyed by message id. */
export type StoredFile = FileMeta & {
    peerId: number;
    blob: Blob;
    ts: number;
};

/** Cached public profile row so the contact list renders instantly / offline. */
export type CachedUser = {
    id: number;
    display_name: string;
    bio?: string;
    avatar_url?: string | null;
    created_at?: string;
};

class AmraDB extends Dexie {
    messages!: EntityTable<Message, "id">;
    users!: EntityTable<CachedUser, "id">;
    files!: EntityTable<StoredFile, "id">;

    constructor() {
        super("amra");
        this.version(1).stores({
            messages: "id, peerId, ts, [peerId+ts]",
            users: "id, display_name",
        });
        // v2 adds peer-to-peer attachments (images, video, audio, documents).
        this.version(2).stores({
            messages: "id, peerId, ts, [peerId+ts]",
            users: "id, display_name",
            files: "id, peerId, ts",
        });
    }
}

export const db = new AmraDB();

/** All messages of one conversation, oldest first. */
export function conversationMessages(peerId: number) {
    return db.messages.where("peerId").equals(peerId).sortBy("ts");
}

/** Newest message per conversation, keyed by peer id. */
export async function lastMessagesByPeer(): Promise<Record<number, Message>> {
    const rows = await db.messages.orderBy("ts").reverse().limit(500).toArray();
    const map: Record<number, Message> = {};
    for (const row of rows) {
        if (!(row.peerId in map)) map[row.peerId] = row;
    }
    return map;
}
